"use client";

import { type HTMLAttributes, type KeyboardEvent, type ReactNode, useEffect, useRef, useState } from "react";
import { useIndicator } from "../interaction/hooks";
import { cx } from "../utils/cx";

/** Page numbers to show, with `"gap"` where pages are skipped: always the first, last, current and its siblings. */
export function paginationRange(page: number, pageCount: number, siblings = 1): Array<number | "gap"> {
  const total = Math.max(1, Math.floor(pageCount));
  const current = Math.min(Math.max(1, Math.floor(page)), total);
  const slots = siblings * 2 + 5; // first, last, current, two gaps, and the siblings
  if (total <= slots) return Array.from({ length: total }, (_, i) => i + 1);
  // near an edge the list keeps its length by widening the cluster on that side
  const cluster = siblings * 2 + 3;
  const range = (from: number, to: number) => Array.from({ length: to - from + 1 }, (_, i) => from + i);
  if (current <= siblings + 3) return [...range(1, cluster), "gap", total];
  if (current >= total - siblings - 2) return [1, "gap", ...range(total - cluster + 1, total)];
  return [1, "gap", ...range(current - siblings, current + siblings), "gap", total];
}

/** The "…" between page numbers: press it to type the page you want. Enter goes, Escape or leaving the field cancels. */
function PageJump({ total, onJump }: { total: number; onJump: (page: number) => void }) {
  const [editing, setEditing] = useState(false);
  const field = useRef<HTMLInputElement>(null);
  const trigger = useRef<HTMLButtonElement>(null);
  const [text, setText] = useState("");
  useEffect(() => {
    if (editing) field.current?.focus();
  }, [editing]);
  const stop = (refocus: boolean) => {
    setEditing(false);
    setText("");
    if (refocus) queueMicrotask(() => trigger.current?.focus());
  };
  const key = (e: KeyboardEvent<HTMLInputElement>) => {
    if (e.key === "Escape") {
      e.preventDefault();
      stop(true);
    } else if (e.key === "Enter") {
      e.preventDefault();
      const n = Number.parseInt(text, 10);
      if (Number.isFinite(n)) {
        onJump(Math.min(Math.max(1, n), total));
        stop(true);
      }
    }
  };
  return editing ? (
    <input
      ref={field}
      className="hm-page-jump"
      type="text"
      inputMode="numeric"
      autoComplete="off"
      aria-label={`Go to page, 1 to ${total}`}
      placeholder={`1–${total}`}
      value={text}
      onChange={(e) => setText(e.target.value.replace(/\D/g, "").slice(0, String(total).length))}
      onKeyDown={key}
      onBlur={() => stop(false)}
    />
  ) : (
    <button
      ref={trigger}
      type="button"
      className="hm-page-gap-button"
      aria-label="Jump to a page"
      onClick={() => setEditing(true)}
    >
      …
    </button>
  );
}

export type PaginationProps = Omit<HTMLAttributes<HTMLElement>, "onChange"> & {
  page: number;
  pageCount: number;
  onPageChange?: (page: number) => void;
  /** Make each page a real link (for server-rendered or router pages). Takes precedence over buttons. */
  getHref?: (page: number) => string;
  /** Page numbers shown on each side of the current one. Default 1. */
  siblings?: number;
  previousLabel?: ReactNode;
  nextLabel?: ReactNode;
};

/** Previous, numbered pages with gaps, and next. Buttons by default, links with `getHref`. The current-page highlight slides between pages. */
export function Pagination({
  page,
  pageCount,
  onPageChange,
  getHref,
  siblings = 1,
  previousLabel = "Previous",
  nextLabel = "Next",
  className,
  ...rest
}: PaginationProps) {
  const total = Math.max(1, Math.floor(pageCount));
  const current = Math.min(Math.max(1, Math.floor(page)), total);
  const list = useRef<HTMLUListElement>(null);
  useIndicator(list, { item: ".hm-page-link", active: ".hm-page-link[data-current]" });
  const item = (
    target: number,
    content: ReactNode,
    opts: { label?: string; disabled?: boolean; current?: boolean } = {},
  ) => {
    const common = {
      className: "hm-page-link",
      "aria-label": opts.label,
      "aria-current": opts.current ? ("page" as const) : undefined,
      "data-current": opts.current ? "" : undefined,
    };
    if (opts.disabled) {
      return (
        <span {...common} aria-disabled="true">
          {content}
        </span>
      );
    }
    return getHref ? (
      <a {...common} href={getHref(target)}>
        {content}
      </a>
    ) : (
      <button {...common} type="button" onClick={() => onPageChange?.(target)}>
        {content}
      </button>
    );
  };
  return (
    <nav aria-label="Pagination" {...rest} className={cx("hm-pagination", className)}>
      <ul ref={list} className="hm-pagination-list">
        <li>{item(current - 1, previousLabel, { label: "Previous page", disabled: current <= 1 })}</li>
        {paginationRange(current, total, siblings).map((p, i) =>
          p === "gap" ? (
            <li key={`gap-${i}`} className="hm-pagination-gap">
              <PageJump
                total={total}
                onJump={(n) => {
                  if (onPageChange) onPageChange(n);
                  else if (getHref) window.location.assign(getHref(n));
                }}
              />
            </li>
          ) : (
            <li key={p}>{item(p, p, { label: `Page ${p}`, current: p === current })}</li>
          ),
        )}
        <li>{item(current + 1, nextLabel, { label: "Next page", disabled: current >= total })}</li>
      </ul>
    </nav>
  );
}
